async function call(url,body){const res=await fetch(url,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const data=await res.json();if(!res.ok)throw Error(data.error||'Request failed');return data}

function fields(form){const data=new FormData(form);return {name:data.get('name'),subjectTitle:data.get('subjectTitle'),paper:data.get('paper'),canUpload:form.elements.canUpload.checked,canReport:form.elements.canReport.checked,active:form.elements.active.checked}}

async function loadStaff(){const staff=await call('/api/admin/staff');document.getElementById('staffCount').textContent=staff.length+' accounts';const list=document.getElementById('staffList');list.innerHTML=staff.map(u=>`<form class="staff-entry" data-id="${u.id}"><h3>${escapeHtml(u.name)} <span class="badge">${u.active?'Active':'Inactive'}</span></h3><p>Username: <strong>${escapeHtml(u.username)}</strong></p>${!u.subjectTitle?'<p class="hint">Current assignment: all existing topics</p>':''}<div class="grid"><label>Staff name<input name="name" value="${escapeHtml(u.name)}" required maxlength="120"></label><label>Subject / MCQ title<input name="subjectTitle" value="${escapeHtml(u.subjectTitle)}" placeholder="Assign a subject title" required maxlength="160"></label><label>Main heading / Paper<input name="paper" list="papers" value="${escapeHtml(u.paper||'Paper 1')}" required maxlength="80"></label></div><div class="permissions"><label><input name="canUpload" type="checkbox" ${u.canUpload?'checked':''}> Allow question and answer uploads</label><label><input name="canReport" type="checkbox" ${u.canReport?'checked':''}> Allow daily student marks reports</label><label><input name="active" type="checkbox" ${u.active?'checked':''}> Account active</label></div><button type="submit">Save staff access</button><p class="status" role="status"></p></form>`).join('')||'<p>No staff accounts yet.</p>';

 list.querySelectorAll('form').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const status=form.querySelector('.status'),button=form.querySelector('button');button.disabled=true;try{const result=await call('/api/admin/staff/'+form.dataset.id,fields(form));status.style.color='#166534';status.textContent=result.message;form.querySelector('.badge').textContent=form.elements.active.checked?'Active':'Inactive'}catch(e){status.style.color='#b91c1c';status.textContent=e.message}finally{button.disabled=false}})}

