document.getElementById('showPassword').addEventListener('change',event=>{document.getElementById('password').type=event.target.checked?'text':'password'});

let isRegister=false;const requested=new URLSearchParams(location.search).get('role');const portal=['staff','admin'].includes(requested)?requested:'student';const title=portal==='admin'?'Administrator':portal==='staff'?'Staff':'Student';

function render(){document.getElementById('showPassword').checked=false;document.getElementById('password').type='password';document.getElementById('registrationDetails').hidden=!isRegister;document.getElementById('fullName').required=isRegister;document.querySelectorAll('#registrationDetails input').forEach(input=>input.disabled=!isRegister);document.getElementById('form-title').textContent=isRegister?'Register Student Account':title+' Login';document.getElementById('submit-btn').textContent=isRegister?'Register':'Login';document.getElementById('toggle-text').hidden=portal!=='student';document.getElementById('toggle-text').textContent=isRegister?'Already registered? Login':'New student? Register here';document.getElementById('adminLink').hidden=portal!=='staff';document.getElementById('loginHint').textContent=portal==='staff'?'Use the staff account provided by your administrator.':portal==='admin'?'Manage staff accounts, subjects and question upload access.':isRegister?'Create your student account. Your teacher will assign exam access.':'Read announcements and attend exams approved by your teacher.';document.getElementById('password').autocomplete=isRegister?'new-password':'current-password';document.getElementById(portal==='student'?'studentTab':'staffTab').setAttribute('aria-current','page')}

document.getElementById('toggle-text').onclick=()=>{isRegister=!isRegister;document.getElementById('msg').textContent='';render()};render();

document.getElementById('authForm').onsubmit=async event=>{event.preventDefault();const msg=document.getElementById('msg'),button=document.getElementById('submit-btn');button.disabled=true;try{const res=await fetch(isRegister?'/api/register':'/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:document.getElementById('username').value,password:document.getElementById('password').value,code:document.getElementById('twoFactorCode').value.trim(),role:'student',portal,...(isRegister?{fullName:document.getElementById('fullName').value,email:document.getElementById('email').value,studentNumber:document.getElementById('studentNumber').value,className:document.getElementById('className').value}:{})})});const data=await res.json();msg.style.color=res.ok?'#166534':'#b91c1c';if(!res.ok){msg.textContent=data.error;if(data.requiresTwoFactor){document.getElementById('twoFactorField').hidden=false;document.getElementById('twoFactorCode').focus()}return}if(isRegister){isRegister=false;render();msg.textContent=data.message}else location.href=data.role==='admin'?'/admin.html':data.role==='staff'?'/teaching.html':'/student.html'}catch{msg.textContent='Unable to connect. Please try again.'}finally{button.disabled=false}};

