(()=>{const $=id=>document.getElementById(id),escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let page=1,busy=false;
function status(t,error=false){$('activityStatus').textContent=t;$('activityStatus').style.color=error?'#b91c1c':'#166534'}
function url(format='json'){const params={role:$('activityRole').value,timeZone:$('activityTimezone').value,search:$('activitySearch').value,format,page:String(page)};if(!$('activityAllDates').checked){params.from=$('activityFrom').value;params.to=$('activityTo').value;if(!params.from||!params.to)throw Error('Choose both start and end dates.')}return '/api/admin/login-activity?'+new URLSearchParams(params)}
async function load(){if(busy)return;busy=true;try{status('Loading login activity…');const response=await fetch(url()),r=await response.json();if(!response.ok)throw Error(r.error||'Unable to load login activity.');$('activitySummary').innerHTML='<div class="analysis-grid">'+[['Successful logins',r.analysis.logins],['Unique accounts',r.analysis.accounts],['Student logins',r.analysis.studentLogins],['Staff logins',r.analysis.staffLogins]].map(([k,v])=>'<p>'+escape(k)+'<br><strong>'+v+'</strong></p>').join('')+'</div>';$('activityTable').innerHTML=r.rows.length?'<table><thead><tr>'+r.headers.map(h=>'<th>'+escape(h)+'</th>').join('')+'</tr></thead><tbody>'+r.rows.map(row=>'<tr>'+row.map(c=>'<td>'+escape(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table>':'<p>No recorded logins match these filters.</p>';$('activityPage').textContent='Page '+r.page+' of '+r.totalPages+' · '+r.analysis.logins+' matching sign-ins';$('activityPrevious').disabled=page<=1;$('activityNext').disabled=page>=r.totalPages;const start=r.summary.find(s=>s[0]==='Recording started');$('activityRecording').textContent='Recording started: '+(start?.[1]||'Not recorded')+'. Earlier sign-ins cannot be reconstructed.';status(r.subtitle+' · Updated '+new Date(r.generatedAt).toLocaleTimeString())}catch(e){status(e.message,true)}finally{busy=false}}
$('activityForm').onsubmit=e=>{e.preventDefault();page=1;load()};$('activityPrevious').onclick=()=>{if(!busy&&page>1){page--;load()}};$('activityNext').onclick=()=>{if(!busy){page++;load()}};$('activityAllDates').onchange=e=>{for(const id of ['activityFrom','activityTo'])$(id).disabled=e.target.checked};
document.querySelectorAll('[data-activity-format]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{status('Preparing login report…');const response=await fetch(url(button.dataset.activityFormat));if(!response.ok)throw Error((await response.json()).error||'Download failed');const blob=await response.blob(),link=document.createElement('a'),objectUrl=URL.createObjectURL(blob);link.href=objectUrl;link.download=response.headers.get('Content-Disposition')?.match(/filename="([^"]+)"/)?.[1]||'login-activity.'+button.dataset.activityFormat;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(objectUrl),1000);status('Login activity report downloaded.')}catch(e){status(e.message,true)}finally{button.disabled=false}});
(async()=>{try{const response=await fetch('/api/me'),u=await response.json();if(!response.ok||u.role!=='admin'){$('loginActivity').hidden=true;return}const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value])),today=parts.year+'-'+parts.month+'-'+parts.day;$('activityFrom').value=today;$('activityTo').value=today;await load();setInterval(()=>{if(!document.hidden&&$('activityAutoRefresh').checked)load()},60000)}catch(e){status(e.message,true)}})();})();

