ong{font-size:1.35rem}.item{border:1px solid #dce4ef;border-radius:9px;padding:18px;margin:14px 0}.item p{overflow-wrap:anywhere}.wrong{background:#fff0f2;border-left:4px solid #c92f40;color:#a91c2c}.correct{background:#edf9f0;color:#155d34}.options label{display:flex;align-items:flex-start;gap:10px;padding:10px;border:1px solid #e0e6f0;border-radius:7px;margin:8px 0;font-weight:400}.options input{margin-top:6px}.timer{position:sticky;top:0;z-index:2;background:#122c55;color:white;border-radius:10px;padding:14px 18px;display:flex;justify-content:space-between;gap:14px}.member-list{max-height:250px;overflow:auto;border:1px solid #dce4ef;padding:12px}.member-list label{font-weight:400;margin:8px 0}.question-text{white-space:pre-wrap}.editor{border:2px solid #a7bfeb}.tabs{margin-bottom:22px}.tabs a{padding:8px 12px}.progress{height:9px;background:#e6edf7;border-radius:5px;overflow:hidden}.progress span{display:block;height:100%;background:#2969d7}details summary{cursor:pointer;font-weight:600}small{font-size:.86rem}#networkStatus{padding:10px 16px;background:#fff2cb;color:#6e4700;text-align:center}@media(max-width:600px){header{display:block;padding:18px}header nav{margin-top:12px}.card{padding:17px}.grid{grid-template-columns:1fr}.timer{font-size:.9rem}main{padding:0 12px}button{max-width:100%}}

