(()=>{
 const valid=r=>['student','staff','admin'].includes(r),path=location.pathname,query=new URLSearchParams(location.search),loginPage=path==='/'||path==='/index.html';
 let remembered='';try{remembered=sessionStorage.getItem('mcqPortal')||''}catch{}
 const requested=query.get('portal')||query.get('role');
 const role=loginPage?(valid(requested)?requested:'student'):path==='/student.html'?'student':path==='/admin.html'?'admin':['/teaching.html','/staff.html'].includes(path)?(['admin','staff'].includes(requested)?requested:remembered==='admin'?'admin':'staff'):(valid(requested)?requested:valid(remembered)?remembered:'staff');
