$('selectExamClass').onclick=()=>{const group=groups.find(g=>g.id===Number($('examGroup').value));if(!group){status('examStatus','Choose a class, or select individual students below.',true);return}$('examStudents').setStudentIds(group.students)};
$('closePermissions').onclick=()=>$('permissionEditor').hidden=true;$('savePermissions').onclick=async()=>{if(!permissionExamId)return;try{const r=await api('/api/access/exams/'+permissionExamId+'/students',{studentIds:$('permissionStudents').getStudentIds()});status('permissionStatus',r.message);await loadExams()}catch(e){status('permissionStatus',e.message,true)}};

window.refreshTeachingExams=loadExams;
